namespace BookInventory.Application.Iam.Registration;

/// <summary>
/// The capability a registration use case of another module calls to create the login (R53). <c>iam</c> owns the
/// account, the uniqueness of the user id, e-mail and mobile (R1, including the values a rejected application still
/// reserves, R58), the password rules and - for <c>Registration:Mode = InstantLogin</c> - the first session. The user id
/// is generated by the caller, not by <c>iam</c>.
/// <para>
/// It runs inside the caller's request transaction and throws the usual business exceptions (409 duplicate, 400 invalid),
/// which roll that transaction back. The calling module reacts to the account later through <c>UserActivated</c> and
/// <c>UserRejected</c>, raised by the aggregate when a Super Admin approves or rejects the application.
/// </para>
/// </summary>
public interface IMemberUserRegistration
{
    Task<MemberRegistrationResult> RegisterAsync(MemberRegistration registration, CancellationToken cancellationToken = default);
}
